class Solution {
public:
    long long minCost(int m, int n, vector<vector<int>>& waitCost) {
        const long long INF = LLONG_MAX / 4;
        vector<long long> A(n, INF), nA(n);
        A[0] = 1;
        long long F = 1;
        for (int j = 1; j < n; j++) {
            F = (j + 1) + A[j - 1];
            A[j] = F + waitCost[0][j];
        }
        for (int i = 1; i < m; i++) {
            vector<long long> up = A;
            F = (i + 1) + up[0];
            nA[0] = F + waitCost[i][0];
            for (int j = 1; j < n; j++) {
                F = (long long)(i + 1) * (j + 1) + min(up[j], nA[j - 1]);
                nA[j] = F + waitCost[i][j];
            }
            A = nA;
        }
        return F;
    }
};

