class Solution {
    public long minCost(int m, int n, int[][] waitCost) {
        long[] A = new long[n], nA = new long[n];
        java.util.Arrays.fill(A, Long.MAX_VALUE / 4);
        A[0] = 1;
        long F = 1;
        for (int j = 1; j < n; j++) {
            F = (j + 1) + A[j - 1];
            A[j] = F + waitCost[0][j];
        }
        for (int i = 1; i < m; i++) {
            long[] up = A.clone();
            F = (i + 1) + up[0];
            nA[0] = F + waitCost[i][0];
            for (int j = 1; j < n; j++) {
                F = (long)(i + 1) * (j + 1) + Math.min(up[j], nA[j - 1]);
                nA[j] = F + waitCost[i][j];
            }
            A = nA;
        }
        return F;
    }
}

