var minCost = function(m, n, waitCost) {
    const INF = Infinity;
    let A = new Array(n).fill(INF);
    A[0] = 1;
    let F = 1;
    for (let j = 1; j < n; j++) {
        F = (j + 1) + A[j - 1];
        A[j] = F + waitCost[0][j];
    }
    for (let i = 1; i < m; i++) {
        const up = A.slice();
        const nA = new Array(n).fill(INF);
        F = (i + 1) + up[0];
        nA[0] = F + waitCost[i][0];
        for (let j = 1; j < n; j++) {
            F = (i + 1) * (j + 1) + Math.min(up[j], nA[j - 1]);
            nA[j] = F + waitCost[i][j];
        }
        A = nA;
    }
    return F;
};
